export function localizeResearchInfo<T>(value: T, locale: Locale): T {
  if (locale === "uz") return value;
  if (typeof value === "string") {
    const direct = entries[value]?.[locale];
    if (direct) return direct as T;
    const uzLabs = getResearchContent("uz").laboratories.items;
    const localizedLabs = getResearchContent(locale).laboratories.items;
    for (let index = 0; index < uzLabs.length; index += 1) {
      const source = uzLabs[index];
      const target = localizedLabs[index];
      if (value === source.name) return target.name as T;
      if (value === source.description) return target.description as T;
      if (value === source.alt) return target.alt as T;
    }
    return value;
  }
  if (Array.isArray(value)) return value.map((item) => localizeResearchInfo(item, locale)) as T;
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, localizeResearchInfo(item, locale)])) as T;
  }
  return value;
}
